import os
import uuid
import logging
from functools import wraps

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())

all_message = set()
LARGE_FILE_THRESHOLD = 100 * 1024 * 1024


def is_response_too_large_or_binary(response):
    """
    Check if the response is too large or binary.
    """
    if hasattr(response, 'headers'):
        content_length = response.headers.get('Content-Length')
        content_type = response.headers.get('Content-Type', '')

        if content_length and content_length.isdigit():
            if int(content_length) > LARGE_FILE_THRESHOLD:
                return True
        if 'octet-stream' in content_type or 'zip' in content_type:
            return True

    return False


def sanitize_post_params(post_params):
    """
    Sanitize post parameters by replacing binary data with a placeholder.

    :param list post_params: List of tuples containing post parameters.

    :return: List of sanitized post parameters.
    """
    sanitized = []
    if post_params:
        for key, value in post_params:
            if isinstance(value, tuple) and isinstance(value[1], bytes):
                sanitized.append((key, (value[0], b"Binary data suppressed")))
            else:
                sanitized.append((key, value))
    return sanitized


def truncate_log_message(message, max_length=1000):
    """
    Truncate the log message if it exceeds the max_length, ensuring it's a string.

    :param message: The log message, which could be bytes or str.
    :param int max_length: The maximum length of the log message.

    :return: The truncated log message.
    """
    if isinstance(message, bytes):
        try:
            message = message.decode('utf-8')
        except UnicodeDecodeError:
            return "Binary data suppressed"
    return message[:max_length] + '...' if len(message) > max_length else message


def log_request_response(func):  # noqa: C901
    @wraps(func)
    def wrapper(*args, **kwargs):  # noqa: C901
        disable_log = os.getenv("TAF_DCAP_CLIENT_DISABLE_LOGGING", "False").lower() == "true"
        sanitized_kwargs = kwargs.copy()
        request_id = uuid.uuid4()

        try:
            result = func(*args, **kwargs)
            post_params = kwargs.get('post_params')
            sanitized_post_params = sanitize_post_params(post_params)
            sanitized_kwargs['post_params'] = sanitized_post_params
            send_message = "{} {}".format(args[1], sanitized_kwargs)

            if hasattr(result, "stream"):
                response_content = "Streaming response not logged"
            elif hasattr(result, "data"):
                large_or_binary_response = is_response_too_large_or_binary(result)
                if not large_or_binary_response:
                    response_content = truncate_log_message(result.data)
                else:
                    response_content = "Large response data skipped"
            else:
                response_content = "No response data"

            message = f"Send: {send_message} Receive: {response_content}"

            if not disable_log and message not in all_message:
                send_extra = {
                    "request_id": str(request_id),
                    "method": args[0],
                    "url": args[1],
                    "request_args": sanitized_kwargs
                }
                response_extra = {
                    "request_id": str(request_id),
                    "method": args[0],
                    "url": args[1],
                    "status_code": getattr(result, 'status', 'N/A'),
                    "response": response_content
                }

                logger.debug(
                    f"Send message: request_id={request_id} {args[0]} {args[1]} {sanitized_kwargs}",
                    extra={"http_request": send_extra}
                )

                logger.debug(
                    f"Received response: request_id={request_id} {args[0]} {args[1]} "
                    f"{getattr(result, 'status', 'N/A')} {response_content}",
                    extra={"http_response": response_extra}
                )

                all_message.add(message)

            return result

        except Exception as api_err:
            if not disable_log:
                if 'ApiException' in type(api_err).__name__:
                    send_extra = {
                        "request_id": str(request_id),
                        "method": args[0],
                        "url": args[1],
                        "request_args": sanitized_kwargs
                    }
                    logger.debug(
                        f"Send message: request_id={request_id} {args[0]} {args[1]}",
                        extra={"http_request": send_extra}
                    )

                if hasattr(api_err, 'body'):
                    error_log = {
                        "request_id": str(request_id),
                        "method": args[0],
                        "url": args[1],
                        "status_code": api_err.status,
                        "reason": api_err.reason,
                        "body": truncate_log_message(api_err.body)
                    }

                    logger.debug(
                        f"Received response: request_id={error_log['request_id']} {error_log['method']} "
                        f"{error_log['url']} {error_log['status_code']} {error_log['reason']} {error_log['body']}",
                        extra={"http_response": error_log}
                    )
                raise api_err

    return wrapper
